const page = document.body.dataset.page || 'home';

function pageUrl(name) {
  return page === 'login' ? `${name}/` : `../${name}/`;
}

function rootUrl() {
  return page === 'login' ? './' : '../';
}

function currentPageName() {
  return page || 'home';
}

function $(selector, root = document) {
  return root.querySelector(selector);
}

function $all(selector, root = document) {
  return Array.from(root.querySelectorAll(selector));
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function showMessage(element, text, type = 'info') {
  if (!element) return;
  element.hidden = false;
  element.textContent = text;
  element.dataset.type = type;
}

function getNextPage() {
  const next = new URLSearchParams(location.search).get('next');
  const clean = String(next || '').replace('.html', '').replace(/\/$/, '');
  return /^[a-z0-9_-]+$/i.test(clean) ? pageUrl(clean) : pageUrl('home');
}

function applyLocalSettings(settings = {}) {
  if (settings.accent_color) document.documentElement.style.setProperty('--accent', settings.accent_color);
  document.body.classList.toggle('reduced-motion', Boolean(settings.reduced_motion));
  document.body.classList.toggle('compact-mode', Boolean(settings.compact_mode));
}

function isModReviewer(session) {
  return String(session?.user?.email || '').trim().toLowerCase() === MOD_REVIEWER_EMAIL;
}

async function getSession() {
  const { data } = await supabase.auth.getSession();
  return data.session;
}

async function requireSession() {
  const session = await getSession();
  if (!session) {
    const next = encodeURIComponent(currentPageName());
    location.href = `${rootUrl()}?next=${next}`;
    return null;
  }
  return session;
}

async function trackEvent(eventType, details = {}) {
  try {
    const session = await getSession();
    if (!session?.access_token) return;
    await fetch(`${SUPABASE_URL}/functions/v1/track-event`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${session.access_token}`,
      },
      body: JSON.stringify({ event_type: eventType, page: currentPageName(), details }),
    });
  } catch (_) {}
}

async function initLogin() {
  const session = await getSession();
  if (session) {
    location.href = getNextPage();
    return;
  }

  const form = $('#loginForm');
  const message = $('#authMessage');

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const email = String(data.get('email') || '').trim();
    const password = String(data.get('password') || '');

    showMessage(message, 'Проверяю данные...');

    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) {
      showMessage(message, error.message || 'Не удалось войти.', 'error');
      return;
    }

    await trackEvent('login', { method: 'password' });
    location.href = getNextPage();
  });
}

async function initRegister() {
  const session = await getSession();
  if (session) {
    location.href = pageUrl('home');
    return;
  }

  const form = $('#registerForm');
  const message = $('#authMessage');

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const nickname = String(data.get('nickname') || '').trim() || 'DexxureUser';
    const email = String(data.get('email') || '').trim();
    const password = String(data.get('password') || '');

    if (password.length < 6) {
      showMessage(message, 'Пароль должен быть минимум 6 символов.', 'error');
      return;
    }

    showMessage(message, 'Создаю аккаунт...');

    const { data: signUpData, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { nickname } },
    });

    if (error) {
      const text = /already registered/i.test(error.message)
        ? 'Этот email уже зарегистрирован. Перейди на страницу входа.'
        : error.message || 'Не удалось создать аккаунт.';
      showMessage(message, text, 'error');
      return;
    }

    if (signUpData.session && signUpData.user) {
      await supabase.from('user_settings').upsert({
        user_id: signUpData.user.id,
        nickname,
        accent_color: '#b7ff00',
        scanlines: true,
        compact_mode: false,
        reduced_motion: false,
      });
      await trackEvent('register', { method: 'password' });
      location.href = pageUrl('home');
    } else {
      showMessage(message, 'Аккаунт создан. Проверь почту, если включено подтверждение email.', 'success');
    }
  });
}

async function initShell() {
  const session = await requireSession();
  if (!session) return;

  const user = session.user;
  const badge = $('#userBadge');
  if (badge) badge.textContent = user.email || 'Profile';

  $('#logoutButton')?.addEventListener('click', async () => {
    await trackEvent('logout');
    await supabase.auth.signOut();
    location.href = rootUrl();
  });

  $('#navToggle')?.addEventListener('click', () => $('.nav')?.classList.toggle('is-open'));

  $all('.nav a').forEach((link) => {
    const target = (link.getAttribute('href') || '').replaceAll('../', '').replaceAll('/', '').replace('.html', '');
    if (target === page) link.classList.add('is-active');
  });

  const { data } = await supabase.from('user_settings').select('*').eq('user_id', user.id).maybeSingle();
  if (data) applyLocalSettings(data);
}

async function initHome() {
  const approvedMods = await supabase.from('mods').select('id', { count: 'exact', head: true }).eq('status', 'approved');
  const team = await supabase.from('team_members').select('id', { count: 'exact', head: true }).eq('is_visible', true);

  let usersCount = null;
  const siteStats = await supabase.from('site_stats').select('value').eq('key', 'registered_users').maybeSingle();
  if (!siteStats.error && siteStats.data) {
    usersCount = siteStats.data.value;
  } else {
    const users = await supabase.from('user_settings').select('user_id', { count: 'exact', head: true });
    if (!users.error) usersCount = users.count;
  }

  if ($('#statMods')) $('#statMods').textContent = approvedMods.count ?? 0;
  if ($('#statTeam')) $('#statTeam').textContent = team.count || 4;
  if ($('#statGames')) $('#statGames').textContent = PROJECTS.filter((x) => x.type === 'Игра').length;
  if ($('#statProjects')) $('#statProjects').textContent = PROJECTS.length;
  if ($('#statUsers')) $('#statUsers').textContent = usersCount ?? '—';

  trackEvent('home_opened');
}

function renderGame(project) {
  return `<article class="game-card"><div class="game-card__meta">${escapeHtml(project.type)} · ${escapeHtml(project.category)}</div><h3>${escapeHtml(project.title)}</h3><p>Автор: ${escapeHtml(project.author)}.</p><a class="card-link" href="${escapeHtml(project.url)}" target="_blank" rel="noreferrer">Открыть проект</a></article>`;
}

function initGames() {
  const input = $('#gameSearch');
  const grid = $('#gamesGrid');
  const count = $('#gamesCount');

  const render = () => {
    const query = String(input?.value || '').trim().toLowerCase();
    const filtered = PROJECTS.filter((project) => {
      const haystack = `${project.title}${project.type}${project.category}${project.author}`.toLowerCase();
      return !query || haystack.includes(query);
    });

    if (count) count.textContent = filtered.filter((x) => x.type === 'Игра').length;
    if (grid) {
      grid.innerHTML = filtered.length
        ? filtered.map(renderGame).join('')
        : '<div class="empty-box">Ничего не найдено. Попробуй другой запрос.</div>';
    }
  };

  input?.addEventListener('input', render);
  render();
  trackEvent('games_opened');
}

function renderPost(post) {
  const date = post.published_at ? new Date(post.published_at).toLocaleString('ru-RU') : 'Дата не указана';
  const link = post.telegram_url || TELEGRAM_URL;
  return `<article class="post-card"><div class="post-card__meta">${escapeHtml(date)}</div><h3>${escapeHtml(post.title || 'Публикация Dexxure Games')}</h3><p>${escapeHtml(post.content || 'Текст публикации не добавлен.')}</p><a class="card-link" href="${escapeHtml(link)}" target="_blank" rel="noreferrer">Читать в Telegram</a></article>`;
}

async function initPosts() {
  const grid = $('#postsGrid');
  const openChannel = $('#openChannel');
  if (openChannel) openChannel.href = TELEGRAM_URL;
  if (grid) grid.innerHTML = '<div class="empty-box">Загружаю публикации...</div>';

  const { data, error } = await supabase.from('telegram_posts').select('*').order('published_at', { ascending: false }).limit(12);
  if (error || !data?.length) {
    if (grid) {
      grid.innerHTML = `<div class="empty-box"><h3>Публикации доступны в Telegram</h3><p>Последние публикации можно посмотреть в официальном Telegram-канале DexxureEnt.</p><a class="card-link" href="${TELEGRAM_URL}" target="_blank" rel="noreferrer">Открыть @DexxureEnt</a></div>`;
    }
    return;
  }

  if (grid) grid.innerHTML = data.map(renderPost).join('');
  trackEvent('posts_opened');
}

function renderTeam(member) {
  return `<article class="team-card"><div><div class="role">${escapeHtml(member.role)}</div><h3>${escapeHtml(member.nickname)}</h3><p>${escapeHtml(member.bio)}</p></div><span class="card-link">Dexxure Games</span></article>`;
}

async function initTeam() {
  const grid = $('#teamGrid');
  if (grid) grid.innerHTML = '<div class="empty-box">Загружаю состав...</div>';
  const { data, error } = await supabase.from('team_members').select('*').eq('is_visible', true).order('sort_order', { ascending: true });
  const members = !error && data?.length ? data : FALLBACK_TEAM;
  if (grid) grid.innerHTML = members.map(renderTeam).join('');
  trackEvent('team_opened');
}

function validUrl(value) {
  try {
    const url = new URL(value);
    return ['http:', 'https:'].includes(url.protocol);
  } catch {
    return false;
  }
}

function statusLabel(status) {
  if (status === 'approved') return 'Одобрено';
  if (status === 'rejected') return 'Отклонено';
  return 'На проверке';
}

function renderMod(mod, { review = false } = {}) {
  const date = mod.created_at ? new Date(mod.created_at).toLocaleDateString('ru-RU') : 'Недавно';
  const url = mod.download_url || mod.public_url || mod.file_path;
  const preview = mod.preview_url;
  const reviewActions = review
    ? `<div class="mod-card__actions">
        <button class="primary-button" type="button" data-review-action="approved" data-mod-id="${escapeHtml(mod.id)}">Одобрить</button>
        <button class="secondary-button danger-button" type="button" data-review-action="rejected" data-mod-id="${escapeHtml(mod.id)}">Отклонить</button>
      </div>`
    : '';

  return `<article class="mod-card">
    <div class="mod-card__meta">${escapeHtml(statusLabel(mod.status))} · ${escapeHtml(date)}</div>
    <h3>${escapeHtml(mod.title)}</h3>
    <p>${escapeHtml(mod.description)}</p>
    <p>Игра: ${escapeHtml(mod.game_title)}</p>
    <div class="mod-card__links">
      ${url ? `<a class="card-link" href="${escapeHtml(url)}" target="_blank" rel="noreferrer">Открыть ссылку</a>` : ''}
      ${preview ? `<a class="card-link" href="${escapeHtml(preview)}" target="_blank" rel="noreferrer">Превью</a>` : ''}
    </div>
    ${reviewActions}
  </article>`;
}

async function loadMods() {
  const grid = $('#modsGrid');
  if (grid) grid.innerHTML = '<div class="empty-box">Загружаю мастерскую...</div>';

  const { data, error } = await supabase
    .from('mods')
    .select('*')
    .eq('status', 'approved')
    .order('created_at', { ascending: false })
    .limit(30);

  if (error) {
    if (grid) grid.innerHTML = `<div class="error-box">${escapeHtml(error.message)}</div>`;
    return;
  }

  if (!data?.length) {
    if (grid) grid.innerHTML = '<div class="empty-box"><h3>Мастерская пока пустая</h3><p>Моды появятся здесь после проверки.</p></div>';
    return;
  }

  if (grid) grid.innerHTML = data.map((mod) => renderMod(mod)).join('');
}

async function loadReviewMods() {
  const grid = $('#reviewModsGrid');
  if (!grid) return;
  grid.innerHTML = '<div class="empty-box">Загружаю моды на проверку...</div>';

  const { data, error } = await supabase
    .from('mods')
    .select('*')
    .eq('status', 'pending')
    .order('created_at', { ascending: true })
    .limit(60);

  if (error) {
    grid.innerHTML = `<div class="error-box">${escapeHtml(error.message)}</div>`;
    return;
  }

  if (!data?.length) {
    grid.innerHTML = '<div class="empty-box"><h3>Очередь пустая</h3><p>Новых модов на проверку сейчас нет.</p></div>';
    return;
  }

  grid.innerHTML = data.map((mod) => renderMod(mod, { review: true })).join('');
}

async function reviewModStatus(modId, status, message) {
  showMessage(message, status === 'approved' ? 'Одобряю мод...' : 'Отклоняю мод...');

  const { error } = await supabase
    .from('mods')
    .update({ status, updated_at: new Date().toISOString() })
    .eq('id', modId);

  if (error) {
    showMessage(message, error.message || 'Не удалось изменить статус мода.', 'error');
    return;
  }

  showMessage(message, status === 'approved' ? 'Мод одобрен и теперь виден в мастерской.' : 'Мод отклонён.', 'success');
  await loadReviewMods();
  await loadMods();
}

async function initWorkshop() {
  const session = await getSession();
  const form = $('#modForm');
  const message = $('#uploadMessage');
  const reviewButton = $('#reviewModsButton');
  const reviewPanel = $('#reviewPanel');
  const reviewMessage = $('#reviewMessage');
  const reviewGrid = $('#reviewModsGrid');

  if (isModReviewer(session)) {
    if (reviewButton) reviewButton.hidden = false;
  }

  reviewButton?.addEventListener('click', async () => {
    if (!reviewPanel) return;
    reviewPanel.hidden = !reviewPanel.hidden;
    if (!reviewPanel.hidden) await loadReviewMods();
  });

  reviewGrid?.addEventListener('click', async (event) => {
    const button = event.target.closest('[data-review-action]');
    if (!button) return;

    const modId = button.dataset.modId;
    const status = button.dataset.reviewAction;
    if (!modId || !['approved', 'rejected'].includes(status)) return;

    await reviewModStatus(modId, status, reviewMessage);
  });

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const currentSession = await getSession();
    if (!currentSession) return;

    const data = new FormData(form);
    const title = String(data.get('title') || '').trim();
    const gameTitle = String(data.get('game_title') || '').trim();
    const description = String(data.get('description') || '').trim();
    const downloadUrl = String(data.get('download_url') || '').trim();
    const previewUrl = String(data.get('preview_url') || '').trim();

    if (!title || !gameTitle || !description || !validUrl(downloadUrl)) {
      showMessage(message, 'Заполни поля и укажи правильную ссылку на мод.', 'error');
      return;
    }

    if (previewUrl && !validUrl(previewUrl)) {
      showMessage(message, 'Ссылка на превью указана неправильно.', 'error');
      return;
    }

    showMessage(message, `Отправляю мод на проверку аккаунту Link (${MOD_REVIEWER_EMAIL})...`);

    const { error } = await supabase.from('mods').insert({
      owner_id: currentSession.user.id,
      title,
      game_title: gameTitle,
      description,
      download_url: downloadUrl,
      preview_url: previewUrl || null,
      file_path: downloadUrl,
      public_url: downloadUrl,
      status: 'pending',
    });

    if (error) {
      showMessage(message, error.message || 'Не удалось отправить мод.', 'error');
      return;
    }

    form.reset();
    showMessage(message, 'Мод отправлен на проверку. После одобрения он появится в мастерской.', 'success');
    await trackEvent('mod_url_submitted', { title, game_title: gameTitle });
    await loadMods();
    if (isModReviewer(currentSession) && reviewPanel && !reviewPanel.hidden) await loadReviewMods();
  });

  await loadMods();
  trackEvent('workshop_opened');
}

async function initSettings() {
  const session = await getSession();
  const form = $('#settingsForm');
  const message = $('#settingsMessage');
  if (!session || !form) return;

  const { data } = await supabase.from('user_settings').select('*').eq('user_id', session.user.id).maybeSingle();
  const settings = data || {
    nickname: session.user.user_metadata?.nickname || session.user.email?.split('@')[0] || 'DexxureUser',
    accent_color: '#b7ff00',
    scanlines: true,
    compact_mode: false,
    reduced_motion: false,
  };

  form.nickname.value = settings.nickname || '';
  form.accent_color.value = settings.accent_color || '#b7ff00';
  form.scanlines.checked = Boolean(settings.scanlines);
  form.compact_mode.checked = Boolean(settings.compact_mode);
  form.reduced_motion.checked = Boolean(settings.reduced_motion);

  applyLocalSettings(settings);

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const nextSettings = {
      user_id: session.user.id,
      nickname: form.nickname.value.trim() || 'DexxureUser',
      accent_color: form.accent_color.value || '#b7ff00',
      scanlines: form.scanlines.checked,
      compact_mode: form.compact_mode.checked,
      reduced_motion: form.reduced_motion.checked,
      updated_at: new Date().toISOString(),
    };

    const { error } = await supabase.from('user_settings').upsert(nextSettings);
    if (error) {
      showMessage(message, error.message || 'Не удалось сохранить настройки.', 'error');
      return;
    }

    applyLocalSettings(nextSettings);
    showMessage(message, 'Настройки сохранены.', 'success');
    await trackEvent('settings_saved', {
      compact_mode: nextSettings.compact_mode,
      reduced_motion: nextSettings.reduced_motion,
    });
  });
}

async function start() {
  if (page === 'login') return initLogin();
  if (page === 'register') return initRegister();

  await initShell();

  if (page === 'home') return initHome();
  if (page === 'games') return initGames();
  if (page === 'posts') return initPosts();
  if (page === 'team') return initTeam();
  if (page === 'workshop') return initWorkshop();
  if (page === 'settings') return initSettings();
  if (page === 'about') trackEvent('about_opened');
}

start();
